<?php require_once __DIR__.'/includes/functions.php'; if(current_user()) redirect(role_home(current_user()['role'])); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf(); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $stmt=db()->prepare('SELECT id,name,email,password_hash,role,status FROM users WHERE email=? LIMIT 1'); $stmt->execute([$email ?: '']); $user=$stmt->fetch(); if($user && $user['role']==='parent' && password_verify($_POST['password']??'', $user['password_hash']) && $user['status']==='active'){session_regenerate_id(true); $_SESSION['user']=['id'=>$user['id'],'name'=>$user['name'],'email'=>$user['email'],'role'=>$user['role']]; redirect(role_home($user['role']));} $error='Parent email or password is incorrect, or this account is not active. Administrators must use the admin sign-in page.';} $pageTitle='Log in'; require __DIR__.'/includes/header.php'; ?>
